/**
 * Assignment has its own permission because a member may reassign work they
 * do not otherwise own. Clearing a set assignee publishes `issue.unassigned`;
 * clearing an empty one publishes nothing. `issue.assigned` stays reserved
 * for a non-null assignee, including a hand-off from one person to another.
 */
export async function assignIssue(
  actor: Actor,
  input: AssignIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:assign", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  if (input.assigneeId === null && before.assigneeId === null) {
    return before;
  }

  const after = await issueRepo.setIssueAssignee(
    input.orgId,
    input.issueId,
    input.assigneeId,
  );

  if (input.assigneeId === null) {
    await emit("issue.unassigned", {
      ...actorEnvelope(actor),
      issueId: after.id,
      projectId: after.projectId,
      previousAssigneeId: before.assigneeId,
    });
    return after;
  }

  await emit("issue.assigned", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    previousAssigneeId: before.assigneeId,
    assigneeId: input.assigneeId,
  });

  return after;
}

/**
 * Drops `userId` from every live issue in the org. Archived issues keep their
 * assignee. Each cleared issue publishes one `issue.unassigned` with `actor`
 * as the actor — the cascade behind removing a member.
 */
export async function unassignLiveIssuesForUser(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  assertOrgScope(actor, orgId);

  const assigned = await issueRepo.listLiveIssuesByAssignee(orgId, userId);
  for (const issue of assigned) {
    if (issue.assigneeId === null) continue;
    const previousAssigneeId = issue.assigneeId;
    const after = await issueRepo.setIssueAssignee(orgId, issue.id, null);
    await emit("issue.unassigned", {
      ...actorEnvelope(actor),
      issueId: after.id,
      projectId: after.projectId,
      previousAssigneeId,
    });
  }
}

  return rows.map((row) => toIssue(row));
}

/** Live issues currently assigned to one user. Archived rows are excluded. */
export async function listLiveIssuesByAssignee(
  orgId: OrgId,
  assigneeId: UserId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.assigneeId, assigneeId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .all();

  return rows.map((row) => toIssue(row));
}

