describe("issue.unassigned", () => {
  it("is emitted once when an assignee is cleared, instead of issue.updated", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Unassign me",
        assigneeId: tenant.userIds.admin,
      }),
    );

    const assigned = capture("issue.assigned");
    const updated = capture("issue.updated");
    const unassigned = capture("issue.unassigned");

    const cleared = await issueService.assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: null,
    });

    expect(cleared.assigneeId).toBeNull();
    expect(assigned).toHaveLength(0);
    expect(updated).toHaveLength(0);
    expect(unassigned).toHaveLength(1);
    expect(unassigned[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.member,
      issueId: issue.id,
      projectId: tenant.project.id,
      previousAssigneeId: tenant.userIds.admin,
    });
  });

  it("publishes nothing when the issue already has no assignee", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Already clear",
      }),
    );

    const assigned = capture("issue.assigned");
    const updated = capture("issue.updated");
    const unassigned = capture("issue.unassigned");

    await issueService.assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: null,
    });

    expect(assigned).toHaveLength(0);
    expect(updated).toHaveLength(0);
    expect(unassigned).toHaveLength(0);
  });

  it("publishes one event per live issue when that assignee is removed", async () => {
    const local = await createTenant("events-unassign-member");
    const live = await issueService.createIssue(
      local.actors.member,
      issueInput(local.org.id, local.project.id, {
        title: "Live assigned",
        assigneeId: local.userIds.member,
      }),
    );
    const second = await issueService.createIssue(
      local.actors.admin,
      issueInput(local.org.id, local.project.id, {
        title: "Also live",
        assigneeId: local.userIds.member,
      }),
    );
    const archived = await issueService.createIssue(
      local.actors.admin,
      issueInput(local.org.id, local.project.id, {
        title: "Archived assigned",
        assigneeId: local.userIds.member,
      }),
    );
    await issueService.archiveIssue(
      local.actors.admin,
      local.org.id,
      archived.id,
    );
    const other = await issueService.createIssue(
      local.actors.admin,
      issueInput(local.org.id, local.project.id, {
        title: "Someone else",
        assigneeId: local.userIds.admin,
      }),
    );

    const unassigned = capture("issue.unassigned");
    const updated = capture("issue.updated");
    const assigned = capture("issue.assigned");

    const target = await memberRepo.findMember(
      local.org.id,
      local.userIds.member,
    );
    if (!target) throw new Error("fixture member missing");

    await memberService.removeMember(local.actors.owner, {
      orgId: local.org.id,
      memberId: target.id,
    });

    expect(updated).toHaveLength(0);
    expect(assigned).toHaveLength(0);
    expect(unassigned).toHaveLength(2);
    expect(unassigned.map((event) => event.issueId).sort()).toEqual(
      [live.id, second.id].sort(),
    );
    for (const event of unassigned) {
      expect(event).toMatchObject({
        orgId: local.org.id,
        actorId: local.userIds.owner,
        projectId: local.project.id,
        previousAssigneeId: local.userIds.member,
      });
    }

    expect(
      (await issueRepo.findIssueById(local.org.id, live.id))?.assigneeId,
    ).toBeNull();
    expect(
      (await issueRepo.findIssueById(local.org.id, second.id))?.assigneeId,
    ).toBeNull();
    expect(
      (await issueRepo.findIssueById(local.org.id, archived.id))?.assigneeId,
    ).toBe(local.userIds.member);
    expect(
      (await issueRepo.findIssueById(local.org.id, other.id))?.assigneeId,
    ).toBe(local.userIds.admin);
  });
});

