/**
 * `issue.unassigned` is a subscribable webhook event. Only enabled endpoints
 * that listed it receive a delivery, and the body is the event payload.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { emit } from "@/lib/event-bus";
import { activityActionSchema } from "@/schemas/activity";
import { notificationKindSchema } from "@/schemas/notification";
import { webhookEventTypeSchema } from "@/schemas/webhook";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import { registerWebhookListeners } from "@/server/services/webhook-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { IssueId, ProjectId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
let detach: Unsubscribe;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("webhook-unassigned", "growth");
  detach = registerWebhookListeners();
});

afterAll(() => {
  detach();
  cleanup();
});

describe("issue.unassigned webhooks", () => {
  it("accepts the new activity, notification, and webhook names", () => {
    expect(activityActionSchema.parse("issue.unassigned")).toBe("issue.unassigned");
    expect(notificationKindSchema.parse("issue_unassigned")).toBe("issue_unassigned");
    expect(webhookEventTypeSchema.parse("issue.unassigned")).toBe("issue.unassigned");
  });

  it("delivers once to each enabled subscriber and skips the rest", async () => {
    const subscribed = await webhookRepo.insertEndpoint(
      {
        orgId: tenant.org.id,
        url: "https://example.test/unassigned",
        eventTypes: ["issue.unassigned"],
      },
      "secret-subscribed",
    );
    const otherEvents = await webhookRepo.insertEndpoint(
      {
        orgId: tenant.org.id,
        url: "https://example.test/created",
        eventTypes: ["issue.created"],
      },
      "secret-other",
    );
    const disabled = await webhookRepo.insertEndpoint(
      {
        orgId: tenant.org.id,
        url: "https://example.test/disabled",
        eventTypes: ["issue.unassigned"],
      },
      "secret-disabled",
    );
    await webhookRepo.updateEndpoint({
      orgId: tenant.org.id,
      webhookId: disabled.id,
      enabled: false,
    });

    const payload = {
      orgId: tenant.org.id,
      actorId: tenant.userIds.admin,
      occurredAt: tenant.org.createdAt,
      issueId: "01HZZZISSUEUNASSIGNED00001" as IssueId,
      projectId: tenant.project.id,
      previousAssigneeId: tenant.userIds.member,
    };

    await emit("issue.unassigned", payload);

    const deliveries = await webhookRepo.claimPendingDeliveries(20);
    const forEvent = deliveries.filter(
      (delivery) =>
        delivery.orgId === tenant.org.id &&
        delivery.eventType === "issue.unassigned",
    );

    expect(forEvent).toHaveLength(1);
    expect(forEvent[0]?.endpointId).toBe(subscribed.id);
    expect(forEvent.map((delivery) => delivery.endpointId)).not.toContain(
      otherEvents.id,
    );
    expect(forEvent.map((delivery) => delivery.endpointId)).not.toContain(
      disabled.id,
    );
    expect(JSON.parse(forEvent[0]?.payload ?? "{}")).toEqual(payload);
  });
});

